s=s.replace("$('play').dataset.game=id;","$('play').dataset.game=id;$('play').dataset.prototype=String(!!g.prototype);")
s=s.replace('fit();engines[id].init();hud();render();','fit();S.mapIndex=pickMap(id);S.mapName=g.maps[S.mapIndex];engines[id].init();applyMap();if(g.prototype)S.message=g.rule;$(\'tag\').textContent=g.tag+\' · \'+S.mapName;hud();render();')
s=s.replace('function finish(winners){if(!S||S.ended)return;','function finish(winners){if(!S||S.ended)return;if(cup){cupFinish(winners);return;}if(S.g.prototype&&prefs.humans===1){let key=\'record-\'+S.g.id;let prev=+localStorage.getItem(key)||0;if(S.scores[0]>prev)localStorage.setItem(key,S.scores[0]);S.message=\'Score \'+S.scores[0]+\' · Record \'+Math.max(prev,S.scores[0]);}')
s=s.replace("let heading=winners.length===S.n?","let heading=S.g.prototype&&prefs.humans===1?(S.scores[0]>=12?'Challenge cleared!':'Keep practising!'):winners.length===S.n?")
s=s.replace("Pocket Party Deluxe 2.0 · Offline","Pocket Party 5.0 Strategy · Offline")
