s=s.replace('// Small stable inspection surface', (p/'expansion-source.js').read_text()+'\n'+(p/'studio-source.js').read_text()+'\n'+(p/'strategy-source.js').read_text()+'\n// Small stable inspection surface')
s=s.replace('(g.prototype?prefs.humans:Math.max(2,prefs.humans))','seatCount(g)')
s=s.replace('S.g.prototype&&prefs.humans===1','S.g.prototype&&S.n===1')
s=s.replace("if(g.prototype)S.message=g.rule;","S.botForm=prefs.consistency==='variable'?chosen([.65,.85,1,1.15,1.35]):1;if(g.prototype)S.message=g.tag.toLowerCase()+' · Touch your coloured side. Pause for full rules.';")
s=s.replace("}[prefs.difficulty]||1);","}[prefs.difficulty]||1)*(S?.botForm||1);")
