s=s.replace("S.g.prototype&&S.n===1?(S.scores[0]>=(S.g.target||12)?'Challenge cleared!':'Keep practising!')", "S.g.prototype&&S.n===1?(S.g.strategic?'Solo run complete!':(S.scores[0]>=(S.g.target||12)?'Challenge cleared!':'Keep practising!'))")
(p/'app/src/main/assets/game.js').write_text(s)
